ansible/roles/core/tasks/main.json:
[
  {
    "ansible.builtin.package": {
      "name": [
        "docker.io",
        "docker-compose"
      ],
      "state": "present",
      "update_cache": true
    },
    "name": "Install the container engine"
  },
  {
    "ansible.builtin.systemd": {
      "enabled": true,
      "name": "docker",
      "state": "started"
    },
    "name": "Start the container engine"
  },
  {
    "ansible.builtin.file": {
      "mode": "0700",
      "path": "/opt/bromigos-lab",
      "state": "directory"
    },
    "name": "Make the lab folder"
  },
  {
    "ansible.builtin.copy": {
      "dest": "/opt/bromigos-lab/",
      "directory_mode": "0755",
      "mode": "0644",
      "src": "{{ playbook_dir }}/../../compose/"
    },
    "name": "Copy the reviewed container definitions"
  },
  {
    "ansible.builtin.shell": {
      "chdir": "/opt/bromigos-lab",
      "cmd": "if docker compose version >/dev/null 2>&1; then docker compose up -d; else docker-compose up -d; fi"
    },
    "changed_when": false,
    "name": "Start selected services without deleting data"
  }
]

compose/Caddyfile:
:80 {
  handle_path /netdata/* {
    reverse_proxy netdata:19999
  }
  handle {
    reverse_proxy homepage:3000
  }
}

compose/compose.yaml:
{
  "services": {
    "caddy": {
      "image": "caddy:2.11.7",
      "ports": [
        "127.0.0.1:80:80",
        "127.0.0.1:443:443"
      ],
      "restart": "unless-stopped",
      "volumes": [
        "./Caddyfile:/etc/caddy/Caddyfile:ro",
        "caddy-data:/data"
      ]
    },
    "homepage": {
      "environment": {
        "HOMEPAGE_ALLOWED_HOSTS": "*"
      },
      "image": "ghcr.io/gethomepage/homepage:v2.5.0",
      "restart": "unless-stopped",
      "volumes": [
        "./homepage:/app/config"
      ]
    },
    "netdata": {
      "environment": {
        "DO_NOT_TRACK": "1"
      },
      "image": "netdata/netdata:v2.12.1",
      "restart": "unless-stopped",
      "volumes": [
        "netdata-data:/var/lib/netdata",
        "/proc:/host/proc:ro",
        "/sys:/host/sys:ro"
      ]
    },
    "restic": {
      "command": [
        "while true; do restic snapshots >/dev/null 2>&1 || restic init; restic backup /data && touch /status/last-success; sleep 86400; done"
      ],
      "entrypoint": [
        "/bin/sh",
        "-c"
      ],
      "environment": {
        "RESTIC_PASSWORD_FILE": "/run/secrets/restic",
        "RESTIC_REPOSITORY": "/repository"
      },
      "image": "restic/restic:0.19.1",
      "restart": "unless-stopped",
      "volumes": [
        "/mnt/backups:/repository",
        "/opt/bromigos-lab:/data/config:ro",
        "caddy-data:/data/caddy:ro",
        "netdata-data:/data/netdata:ro",
        "./restic-password:/run/secrets/restic:ro",
        "backup-status:/status"
      ]
    }
  },
  "volumes": {
    "backup-status": {},
    "caddy-data": {},
    "netdata-data": {}
  }
}

